-- ========== 通知 ==========
local PlayerGui = lp:WaitForChild("PlayerGui")
local old = PlayerGui:FindFirstChild("MasterBuilderUI")
if old then old:Destroy() end

local screenGui = Instance.new("ScreenGui")
screenGui.Name = "MasterBuilderUI"
screenGui.ResetOnSpawn = false
screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
screenGui.IgnoreGuiInset = true
screenGui.Parent = PlayerGui

local notifContainer = Instance.new("Frame")
notifContainer.AnchorPoint = Vector2.new(1,1)
notifContainer.Position = UDim2.new(1,-12,1,-12)
notifContainer.Size = UDim2.new(0,px(160),1,-24)
notifContainer.BackgroundTransparency = 1
notifContainer.ZIndex = 100
notifContainer.Parent = screenGui
local notifLayout = Instance.new("UIListLayout")
notifLayout.SortOrder = Enum.SortOrder.LayoutOrder
notifLayout.VerticalAlignment = Enum.VerticalAlignment.Bottom
notifLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
notifLayout.Padding = UDim.new(0,6)
notifLayout.Parent = notifContainer
local notifSeq = 0

local function notify(text, kind)
    kind = kind or "info"
    notifSeq = notifSeq + 1
    local order = notifSeq
    local bgMap = {success=C.green_bg, error=C.red_bg, warn=Color3.fromRGB(255,230,180), info=C.blue_bg}
    local txMap = {success=C.green_tx, error=C.red_tx, warn=Color3.fromRGB(140,100,40),  info=C.blue_tx}
    local card = Instance.new("Frame")
    card.LayoutOrder = order
    card.Size = UDim2.new(0,px(150),0,0)
    card.AutomaticSize = Enum.AutomaticSize.Y
    card.BackgroundColor3 = bgMap[kind] or C.blue_bg
    card.BackgroundTransparency = 1
    card.BorderSizePixel = 0
    card.ZIndex = 101
    card.Parent = notifContainer
    Instance.new("UICorner",card).CornerRadius = UDim.new(0,px(10))
    local st = Instance.new("UIStroke",card)
    st.Color = bgMap[kind] or C.blue_bg
    st.Thickness = 1; st.Transparency = 1
    local pad = Instance.new("UIPadding",card)
    pad.PaddingTop=UDim.new(0,8); pad.PaddingBottom=UDim.new(0,8)
    pad.PaddingLeft=UDim.new(0,10); pad.PaddingRight=UDim.new(0,10)
    local lbl = Instance.new("TextLabel",card)
    lbl.BackgroundTransparency=1; lbl.Size=UDim2.new(1,0,0,0)
    lbl.AutomaticSize=Enum.AutomaticSize.Y
    lbl.Text=tostring(text); lbl.TextColor3=txMap[kind] or C.blue_tx
    lbl.TextWrapped=true; lbl.Font=Enum.Font.GothamMedium
    lbl.TextSize=px(9); lbl.TextXAlignment=Enum.TextXAlignment.Left
    lbl.TextTransparency=1; lbl.ZIndex=102
    TweenService:Create(card,TweenInfo.new(0.18),{BackgroundTransparency=0.05}):Play()
    TweenService:Create(lbl,TweenInfo.new(0.18),{TextTransparency=0}):Play()
    TweenService:Create(st,TweenInfo.new(0.18),{Transparency=0.2}):Play()
    task.delay(2.5,function()
        if not card.Parent then return end
        TweenService:Create(card,TweenInfo.new(0.2),{BackgroundTransparency=1}):Play()
        TweenService:Create(lbl,TweenInfo.new(0.2),{TextTransparency=1}):Play()
        TweenService:Create(st,TweenInfo.new(0.2),{Transparency=1}):Play()
        task.wait(0.25); card:Destroy()
    end)
end

-- ========== 主框架 ==========
local FRAME_W = px(250)
local FRAME_H = px(200)

local mainFrame = Instance.new("Frame")
mainFrame.Name = "Main"
mainFrame.Size = UDim2.new(0,FRAME_W,0,FRAME_H)
mainFrame.Position = UDim2.new(0.08,0,0.38,0)
mainFrame.BackgroundColor3 = C.bg
mainFrame.BackgroundTransparency = 0.04
mainFrame.BorderSizePixel = 0
mainFrame.ClipsDescendants = true
mainFrame.Parent = screenGui
Instance.new("UICorner",mainFrame).CornerRadius = UDim.new(0,px(14))
local mStroke = Instance.new("UIStroke",mainFrame)
mStroke.Color = C.stroke; mStroke.Thickness = math.max(1,S*1.2); mStroke.Transparency = 0.15

do
    local drag, dragStart, startPos = false
    mainFrame.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1
        or inp.UserInputType == Enum.UserInputType.Touch then
            drag = true; dragStart = inp.Position; startPos = mainFrame.Position
            inp.Changed:Connect(function()
                if inp.UserInputState == Enum.UserInputState.End then drag = false end
            end)
        end
    end)
    mainFrame.InputChanged:Connect(function(inp)
        if drag and (inp.UserInputType == Enum.UserInputType.MouseMovement
            or inp.UserInputType == Enum.UserInputType.Touch) then
            local d = inp.Position - dragStart
            mainFrame.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset+d.X,
                startPos.Y.Scale, startPos.Y.Offset+d.Y)
        end
    end)
end

local titleLbl = Instance.new("TextLabel",mainFrame)
