-- ========== 选项卡 ==========
local TAB_Y = px(38)
local TAB_H = px(22)
local tabNames = {"Pyramid","JuroShop","Scanner"}
local tabBtns = {}
local tabPanels = {}
local currentTab = "Pyramid"

local tabBar = Instance.new("Frame",mainFrame)
tabBar.Size = UDim2.new(1,-px(20),0,TAB_H)
tabBar.Position = UDim2.new(0,px(10),0,TAB_Y)
tabBar.BackgroundTransparency = 1

local tabW = math.floor((FRAME_W - px(20)) / 3)
for i, name in ipairs(tabNames) do
    local btn = Instance.new("TextButton",tabBar)
    btn.Size = UDim2.new(0,tabW-2,1,0)
    btn.Position = UDim2.new(0,(i-1)*(tabW),0,0)
    btn.BackgroundColor3 = (name == currentTab) and C.tab_sel or C.tab_un
    btn.BorderSizePixel = 0
    btn.Text = name
    btn.TextColor3 = (name == currentTab) and C.tab_sel_tx or C.tab_un_tx
    btn.Font = Enum.Font.GothamMedium
    btn.TextSize = px(9)
    btn.AutoButtonColor = false
    Instance.new("UICorner",btn).CornerRadius = UDim.new(0,px(6))
    tabBtns[name] = btn

    local panel = Instance.new("Frame",mainFrame)
    panel.Size = UDim2.new(1,-px(20),0,FRAME_H - TAB_Y - TAB_H - px(10))
    panel.Position = UDim2.new(0,px(10),0,TAB_Y+TAB_H+px(4))
    panel.BackgroundTransparency = 1
    panel.Visible = (name == currentTab)
    tabPanels[name] = panel
end

local function switchTab(name)
    currentTab = name
    for _, n in ipairs(tabNames) do
        tabBtns[n].BackgroundColor3 = (n==name) and C.tab_sel or C.tab_un
        tabBtns[n].TextColor3 = (n==name) and C.tab_sel_tx or C.tab_un_tx
        tabPanels[n].Visible = (n==name)
    end
end
for _, name in ipairs(tabNames) do
    tabBtns[name].MouseButton1Click:Connect(function() switchTab(name) end)
end

local function makeBtn(parent, pos, size, bg, tx, txt)
    local btn = Instance.new("TextButton",parent)
    btn.Size = size
    btn.Position = pos
    btn.BackgroundColor3 = bg
    btn.BorderSizePixel = 0
    btn.Text = txt
    btn.TextColor3 = tx
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = px(10)
    btn.AutoButtonColor = false
    Instance.new("UICorner",btn).CornerRadius = UDim.new(0,px(8))
    return btn
end

local function makeLabel(parent, pos, size, txt, color)
    local lbl = Instance.new("TextLabel",parent)
    lbl.Size = size
    lbl.Position = pos
    lbl.BackgroundTransparency = 1
    lbl.Font = Enum.Font.GothamMedium
    lbl.TextSize = px(9)
    lbl.TextColor3 = color or C.label
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.Text = txt
    return lbl
end

local running = false
local function stopAll() running = false end

local function buildModelIndex()
    local idx = {}
    for _, m in ipairs(workspace:GetDescendants()) do
        if m:IsA("Model") then
            local ownerVal = m:FindFirstChild("Owner")
            if ownerVal and ownerVal.Value == lp then
                local pp = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart")
                if pp then
                    local pos = pp.Position
                    local key = math.floor(pos.X+0.5).."_"..math.floor(pos.Y+0.5).."_"..math.floor(pos.Z+0.5)
                    idx[key] = m
                end
            end
        end
    end
    return idx
end

local function findModel(idx, x, y, z)
    local key = math.floor(x+0.5).."_"..math.floor(y+0.5).."_"..math.floor(z+0.5)
    if idx[key] then return idx[key] end
    for dx = -2,2 do for dy = -2,2 do for dz = -2,2 do
        local k2 = (math.floor(x+0.5)+dx).."_"..(math.floor(y+0.5)+dy).."_"..(math.floor(z+0.5)+dz)
        if idx[k2] then return idx[k2] end
    end end end
    return nil
end

-- ========== PYRAMID 面板 ==========
do
    local p = tabPanels["Pyramid"]
    makeLabel(p, UDim2.new(0,0,0,px(2)), UDim2.new(0,px(40),0,px(18)), "Color:")
    local colorBox = Instance.new("TextBox",p)
    colorBox.Size = UDim2.new(0,px(90),0,px(18))
    colorBox.Position = UDim2.new(0,px(42),0,px(2))
    colorBox.BackgroundColor3 = Color3.fromRGB(240,232,248)
    colorBox.BorderSizePixel = 0
    colorBox.Text = "Birch"
    colorBox.Font = Enum.Font.GothamMedium
    colorBox.TextSize = px(9)
    colorBox.TextColor3 = C.label
    colorBox.PlaceholderText = "Birch"
    Instance.new("UICorner",colorBox).CornerRadius = UDim.new(0,px(6))

    local progLbl = makeLabel(p, UDim2.new(0,0,0,px(24)), UDim2.new(1,0,0,px(14)), "Place: 0/"..#DATA_PYRAMID)

    local BW = math.floor((FRAME_W-px(20)-px(8))/3)
    local startBtn = makeBtn(p, UDim2.new(0,0,0,px(42)),           UDim2.new(0,BW,0,px(22)), C.green_bg, C.green_tx, "Start")
    local stopBtn  = makeBtn(p, UDim2.new(0,BW+px(4),0,px(42)),    UDim2.new(0,BW,0,px(22)), C.red_bg,   C.red_tx,   "Stop")
    local paintBtn = makeBtn(p, UDim2.new(0,(BW+px(4))*2,0,px(42)),UDim2.new(0,BW,0,px(22)), C.blue_bg,  C.blue_tx,  "Paint")

    startBtn.MouseButton1Click:Connect(function()
        if running then notify("已在运行中","warn") return end
        running = true
        local total = #DATA_PYRAMID
        notify("开始放置 "..total.." 块","success")
        task.spawn(function()
            for i, d in ipairs(DATA_PYRAMID) do
                if not running then break end
                local cf = CFrame.new(d.x,d.y,d.z,d.r00,d.r01,d.r02,d.r10,d.r11,d.r12,d.r20,d.r21,d.r22)
                pcall(function() placeRemote:FireServer(d.n, cf, lp) end)
                progLbl.Text = "Place: "..i.."/"..total
                task.wait(0.005)
            end
            if running then notify("金字塔放置完成","success") end
            running = false
        end)
    end)

    stopBtn.MouseButton1Click:Connect(stopAll)

    paintBtn.MouseButton1Click:Connect(function()
        if running then notify("已在运行中","warn") return end
        running = true
        local colorName = colorBox.Text ~= "" and colorBox.Text or "Birch"
        notify("开始涂色 ("..colorName..")","info")
        task.spawn(function()
            local idx = buildModelIndex()
            local total = #DATA_PYRAMID
            local painted = 0
            for i, d in ipairs(DATA_PYRAMID) do
                if not running then break end
                local m = findModel(idx, d.x, d.y, d.z)
                if m then
                    pcall(function() paintRemote:FireServer(m, colorName) end)
                    painted = painted + 1
                end
                if i % 100 == 0 then
                    progLbl.Text = "Paint: "..i.."/"..total
                    task.wait(0.005)
                end
            end
            notify("涂色完成 "..painted.."/"..total,"success")
            progLbl.Text = "Paint done: "..painted.."/"..total
            running = false
        end)
    end)
end

