-- ========== SCANNER 面板 ==========
do
    local p = tabPanels["Scanner"]
    local selectedOwner = nil
    local scanResult = ""

    makeLabel(p, UDim2.new(0,0,0,0), UDim2.new(0,px(40),0,px(14)), "Owner:")
    local scanOwnBtn = makeBtn(p, UDim2.new(1,-px(80),0,0), UDim2.new(0,px(78),0,px(16)), C.blue_bg, C.blue_tx, "Scan Owners")
    scanOwnBtn.TextSize = px(8)

    local ownerScroll = Instance.new("ScrollingFrame",p)
    ownerScroll.Size = UDim2.new(1,0,0,px(50))
    ownerScroll.Position = UDim2.new(0,0,0,px(18))
    ownerScroll.BackgroundColor3 = Color3.fromRGB(240,232,248)
    ownerScroll.BorderSizePixel = 0
    ownerScroll.ScrollBarThickness = 4
    ownerScroll.CanvasSize = UDim2.new(0,0,0,0)
    ownerScroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
    Instance.new("UICorner",ownerScroll).CornerRadius = UDim.new(0,px(6))
    local ownerLayout = Instance.new("UIListLayout",ownerScroll)
    ownerLayout.SortOrder = Enum.SortOrder.LayoutOrder
    ownerLayout.Padding = UDim.new(0,2)

    scanOwnBtn.MouseButton1Click:Connect(function()
        for _, c in ipairs(ownerScroll:GetChildren()) do
            if c:IsA("TextButton") then c:Destroy() end
        end
        local seen = {}
        for _, m in ipairs(workspace:GetDescendants()) do
            if m:IsA("Model") then
                local ov = m:FindFirstChild("Owner")
                if ov and ov.Value and ov.Value ~= "" then
                    local name = ""
                    if typeof(ov.Value) == "Instance" and ov.Value:IsA("Player") then
                        name = ov.Value.Name
                    elseif type(ov.Value) == "string" then
                        name = ov.Value
                    end
                    if name ~= "" and not seen[name] then
                        seen[name] = true
                        local btn = Instance.new("TextButton",ownerScroll)
                        btn.Size = UDim2.new(1,-4,0,px(16))
                        btn.BackgroundColor3 = C.tab_un
                        btn.BorderSizePixel = 0
                        btn.Text = name
                        btn.TextColor3 = C.tab_un_tx
                        btn.Font = Enum.Font.GothamMedium
                        btn.TextSize = px(9)
                        btn.AutoButtonColor = false
                        Instance.new("UICorner",btn).CornerRadius = UDim.new(0,px(4))
                        btn.MouseButton1Click:Connect(function()
                            selectedOwner = name
                            for _, c2 in ipairs(ownerScroll:GetChildren()) do
                                if c2:IsA("TextButton") then
                                    c2.BackgroundColor3 = C.tab_un
                                    c2.TextColor3 = C.tab_un_tx
                                end
                            end
                            btn.BackgroundColor3 = C.tab_sel
                            btn.TextColor3 = C.tab_sel_tx
                        end)
                    end
                end
            end
        end
        notify("Owner 扫描完成","success")
    end)

    local scanBpBtn = makeBtn(p, UDim2.new(0,0,0,px(72)),      UDim2.new(0,px(100),0,px(18)), C.blue_bg,   C.blue_tx,   "Scan Blueprints")
    local copyBtn   = makeBtn(p, UDim2.new(0,px(104),0,px(72)),UDim2.new(0,px(80),0,px(18)),  C.purple_bg, C.purple_tx, "Copy Result")
    scanBpBtn.TextSize = px(8); copyBtn.TextSize = px(8)

    local resultLbl = makeLabel(p, UDim2.new(0,0,0,px(94)), UDim2.new(1,0,0,px(14)), "Scan: ready")

    scanBpBtn.MouseButton1Click:Connect(function()
        if not selectedOwner then notify("请先选择 Owner","warn") return end
        local lines = {}
        local count = 0
        for _, m in ipairs(workspace:GetDescendants()) do
            if m:IsA("Model") then
                local typeVal = m:FindFirstChild("Type")
                local ownerVal = m:FindFirstChild("Owner")
                local itemVal = m:FindFirstChild("ItemName") or m:FindFirstChild("PurchasedBoxItemName")
                local woodVal = m:FindFirstChild("BlueprintWoodClass")
                local ownerName = ""
                if ownerVal then
                    if typeof(ownerVal.Value)=="Instance" and ownerVal.Value:IsA("Player") then
                        ownerName = ownerVal.Value.Name
                    elseif type(ownerVal.Value)=="string" then
                        ownerName = ownerVal.Value
                    end
                end
                if typeVal and typeVal.Value == "Blueprint" and ownerName == selectedOwner then
                    count = count + 1
                    local pp = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart")
                    local pos = pp and pp.Position or Vector3.new(0,0,0)
                    local iname = itemVal and tostring(itemVal.Value) or m.Name
                    local wood = woodVal and tostring(woodVal.Value) or "?"
                    table.insert(lines, string.format('[%d] "%s" | Wood: %s | pos(%.1f,%.1f,%.1f)',
                        count, iname, wood, pos.X, pos.Y, pos.Z))
                end
            end
        end
        scanResult = table.concat(lines, "\n")
        resultLbl.Text = "Scan: "..count.." 条"
        notify("扫描完成 "..count.." 条","success")
    end)

    copyBtn.MouseButton1Click:Connect(function()
        if scanResult == "" then notify("没有扫描结果","warn") return end
        pcall(function() setclipboard(scanResult) end)
        notify("已复制到剪贴板","success")
    end)
end

